import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, float, mix, smoothstep, fract, sin, dot, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, TorusKnotGeometry, LatheGeometry, Vector2, Color, DirectionalLight, PointLight } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const cBg = colors.background ?? '#0b0b10';
  const cSurface = colors.surface ?? '#14141a';
  const cPaper = colors.paper ?? '#e8ecf2';
  const cAccent = colors.accent ?? '#ff2a38';
  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];

  const group = new Group();
  const disposables = [];
  const primitiveHandles = [];
  const timelines = [];

  // ---------- Backdrop: 7x6 gradient plane at z=-3 ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const y = uv().y;
    const s0 = new Color(stops[0].hex);
    const s1 = new Color(stops[1].hex);
    const s2 = new Color(stops[2].hex);
    const a1 = float(stops[1].at);
    const c01 = mix(vec3(s0.r, s0.g, s0.b), vec3(s1.r, s1.g, s1.b), smoothstep(float(stops[0].at), a1, y));
    backdropMat.colorNode = mix(c01, vec3(s2.r, s2.g, s2.b), smoothstep(a1, float(stops[2].at), y));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------- Pedestal: lathe with 0.03 chamfered top edge, top face y=-0.35 ----------
  const pedestalPts = [
    new Vector2(0.0, 0.0),
    new Vector2(1.1, 0.0),
    new Vector2(1.1, 0.47),
    new Vector2(1.07, 0.5),
    new Vector2(0.0, 0.5),
  ];
  const pedestalGeo = new LatheGeometry(pedestalPts, 64);
  const pedestalMat = new MeshStandardNodeMaterial({
    color: new Color(cSurface),
    roughness: 0.7,
    metalness: 0.35,
  });
  const pedestal = new Mesh(pedestalGeo, pedestalMat);
  pedestal.position.set(0, -0.85, 0); // bottom at -0.85, top face at -0.35
  group.add(pedestal);
  disposables.push(pedestalGeo, pedestalMat);

  // ---------- Contact shadow: radial gradient plane, radius 1.5, y=-0.36 ----------
  const shadowGeo = new PlaneGeometry(3, 3);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const d = uv().sub(vec2(0.5, 0.5)).length().mul(float(3.0)); // distance in scene units
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
    shadowMat.opacityNode = float(1.0).sub(smoothstep(float(0.2), float(1.5), d)).mul(float(0.6));
  }
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -0.36, 0);
  group.add(contactShadow);
  disposables.push(shadowGeo, shadowMat);

  // ---------- Torus knot: brushed-metal PBR, imperfection pass ----------
  const knotGeo = new TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMat = new MeshPhysicalNodeMaterial({
    color: new Color(cPaper).multiplyScalar(0.72),
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
  });
  knotMat.anisotropy = 0.9;
  knotMat.anisotropyRotation = Math.PI / 2; // 90 deg to tube direction
  knotMat.envMapIntensity = 0.7;
  const knotGroup = new Group();
  const knot = new Mesh(knotGeo, knotMat);
  knotGroup.add(knot);
  knotGroup.position.set(0, 0.4, 0);
  group.add(knotGroup);
  disposables.push(knotGeo, knotMat);

  // Brushed-metal roughness map (multiplies base 0.55) + 2% value jitter + scratch normal pass
  let brushedTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      brushedTex = tex;
      if (tex.center) tex.center.set(0.9, 0.9);
      const jitter = fract(
        sin(dot(uv().mul(float(240.0)), vec2(12.9898, 78.233))).mul(float(43758.5453))
      );
      // roughness = map * base, broken up by 2% value jitter so highlights streak
      knotMat.roughnessNode = texture(tex).r
        .mul(float(0.55))
        .mul(jitter.mul(float(0.04)).add(float(0.98)));
      // imperfection pass: reuse map as scratch bump at strength 0.15 equivalent
      knotMat.bumpMap = tex;
      knotMat.bumpScale = 0.15 * 0.1;
      knotMat.needsUpdate = true;
    });
  }

  // ---------- Node-local lights: rim/back opposite the scene key ----------
  const rim = new DirectionalLight(new Color(cAccent).lerp(new Color(cPaper), 0.55), 0.8);
  rim.position.set(-2.5, 1.4, -2.2);
  rim.target = knotGroup;
  group.add(rim);

  const fill = new PointLight(new Color(cPaper), 0.5, 12, 2);
  fill.position.set(2.2, -0.4, 2.6);
  group.add(fill);

  // ---------- Text: verbatim spec copy on the 0.25 rhythm ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (item.role === 'headline') {
      const h = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 68,
        color: cPaper,
        align: 'center',
      });
      h.position.set(0, -1.2, 0.2);
      group.add(h);
    } else if (item.role === 'caption') {
      const c = ctx.fontAtlas.createText(item.text, {
        fontSize: item.typography?.fontSize ?? 18,
        color: cPaper,
        align: 'center',
        letterSpacingPx: (item.typography?.fontSize ?? 18) * 0.08,
      });
      c.position.set(0, -1.6, 0.2);
      group.add(c);
    }
  }

  // ---------- Cinematic primitives ----------
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[prim.name];
    if (fn) primitiveHandles.push(fn(knotGroup, prim.params ?? {}));
  }

  // ---------- Entrance: rise-in + weighted settle ----------
  knotGroup.position.y = 0.4 - 0.35;
  knotGroup.scale.setScalar(0.96);
  const tl = gsap.timeline();
  tl.to(knotGroup.position, { y: 0.4, duration: 0.7, ease: 'power3.out' })
    .to(knotGroup.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power2.out' }, 0.2)
    .to(knotGroup.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, '>');
  timelines.push(tl);

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    for (const t of timelines) t.kill();
    for (const p of primitiveHandles) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
    for (const d of disposables) d.dispose();
    if (brushedTex && brushedTex.dispose) brushedTex.dispose();
    rim.dispose?.();
    fill.dispose?.();
  };

  return group;
}
